{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10", "C18", "C83", "C147", "C130", "C154", "C128", "C114"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C18", "C83", "C147", "C130", "C154"],
  "claims": [
    {
      "claim": "The query is pitavastatin free acid; the closest measured context, cerivastatin, shares the 3,5-dihydroxyhept-6-enoic acid side chain and a fluorophenyl substituent and had absolute oral bioavailability 60% (90% CI 51-70%) in fasted healthy young men, with the lower bound well above the 20% threshold.",
      "card_ids": ["C10", "C18"]
    },
    {
      "claim": "L3 card C83 shows that after an oral pitavastatin microdose, the pitavastatin lactone metabolite was measurable in plasma (rifampin GMR ~0.9 for Cmax and AUC), confirming oral absorption and systemic exposure of the pitavastatin scaffold; this is supportive but does not quantify absolute F.",
      "card_ids": ["C83"]
    },
    {
      "claim": "L4 card C147 shows cerivastatin sodium is freely soluble in water with rapid dissolution (>80% within 15 min), supporting the solubility/dissolution component for the closely related statin acid side chain; C130 shows atorvastatin has a Caco-2 AP-BL Papp of 1.8 ± 0.3 x10^-6 cm/s, supporting intestinal permeability for this statin class.",
      "card_ids": ["C147", "C130"]
    },
    {
      "claim": "C154 shows atorvastatin calcium has aqueous solubility of about 1.23 mg/mL at pH 6.0, and C128/C114 show acidic statins such as rosuvastatin have pH-dependent solubility with log S about -2.5, supporting adequate dissolution/solubility for the acidic statin class; no transferable L4 record provides affirmative evidence of poor absorption for the query.",
      "card_ids": ["C154", "C128", "C114"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C147", "C130", "C154", "C128", "C114"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for pitavastatin free acid is present in the supplied cards.",
    "L4 contains no pitavastatin-specific permeability or solubility record; the closest records are cerivastatin sodium and other statins.",
    "Cerivastatin transfer does not control for differences in the quinoline/cyclopropyl core versus the cerivastatin pyridine core, transporter effects, or first-pass metabolism.",
    "First-pass metabolism for pitavastatin is not directly measured; L4 only addresses the absorption component.",
    "C122 (very poor Caco-2 permeability for unrelated M08 carboxylic acids) was considered but judged not transferable to the query's statin scaffold."
  ],
  "decision_summary": "Query is pitavastatin free acid. The closest measured context, cerivastatin, has absolute oral bioavailability 60% (90% CI 51-70%), far above the 20% threshold. L3 shows the pitavastatin scaffold is orally absorbed (lactone metabolite measurable after oral microdose), and L4 adds supportive solubility/dissolution (cerivastatin sodium freely soluble, rapid dissolution) and permeability (atorvastatin Caco-2 Papp 1.8e-6 cm/s) evidence for the statin class. No transferable contradictory evidence appears. Prediction remains high with moderate confidence."
}

